\\
\underbrace{{17 \over 12}\,\pars{1 - {1 \over 578} - {1 \over 668168}}}
_{\ds{=\ \color{#00f}{{222337 \over 157216}}}}
&\approx& \color{#66f}{1.414213\ {\Large\underbrace{5}_{\uparrow}}}\ 6\color{#c00000}{6049\ldots}
\end{array}
$$ 

 $$
\color{#c00000}{\large\color{#66f}{\root{2}}\approx{222337 \over 157216}\approx
