\\[3mm]&<{17 \over 24\root{\pi}}\sum_{n = 3}^{\infty}
{\Gamma\pars{n - 1/2} \over \Gamma\pars{n + 1}}\,{1 \over 289^{n}}
<{17 \over 24\root{\pi}}\,{\Gamma\pars{5/2} \over \Gamma\pars{4}}
